!function(){"use strict";app.factory("aprobacionDocService",(function($injector){let url="/AprobDocument/",mS=$injector.get("mainService"),service={getAll:function(query){return mS.getData("get",url+"Get?json="+JSON.stringify(query)).then(response=>{if("0"===response.code)throw response;if("1"===response.code){let aprobComprobantes;return(JSON.parse(response.payload)||[]).map(item=>({idAprob_Document:item.idAprob_Document,uniqueId:item.uniqueId,fechaEmision:item.fechaEmision,serie:item.serie,serieComprobante:item.serie,identificacionComprador:item.identificacionComprador,razonSocialComprador:item.razonSocialComprador,total:item.total,codEstado:item.codEstado,estado:item.estado,colorFila:item.colorFila}))}}).catch(error=>{throw console.log("Error get all Aprob. Docs service",error),error})},findById:function(id){return mS.getData("get",url+"GetId?id="+id).then(response=>{if("0"===response.code)throw response;if("1"===response.code){let dataRepository=JSON.parse(response.payload);return{comprobante:dataRepository[0][0],detalle:dataRepository[1],infoAdicionalDocumento:dataRepository[2],datosAdicionalesArticulo:dataRepository[3].map(item=>({idDocumento:item.idDocumento,idHistoryInfoAdicional:item.idHistoryInfoAdicional,idArticulo:item.idArticulo,idEtiqueta:item.idEtiqueta,idInfoAdicional:item.idInfoAdicional,jsonAdicional:JSON.parse(item.jsonAdicional),selected:item.selected,estado:item.estado}))}}}).catch(error=>{throw error})},save:function(data){return mS.getData("post",url+"Insert",data).then(response=>response).catch(error=>{throw console.log("Error insert Aprob. Docs service",error),error})},update:function(id,data){return mS.getData("put",url+"Update/"+id,data).then(response=>response).catch(error=>{throw console.log("Error update Aprob. Docs service",error),error})}};return service}))}(window.angular);